import { z } from 'zod';

export const AddDeductionSchema = z.object({
    employee_id: z.string().min(1, 'Employee name field is required.'),
    value: z.string().min(1, 'Value is required'),
    month: z.string().min(1, 'الشهر مطلوب'),
    year: z.string().min(1, 'السنة مطلوبة'),
});

export type AddDeductionFormValues = z.infer<typeof AddDeductionSchema>;
